#pragma once

namespace rbq_sdk::zn {

/// ROS 2 identity of an IDL-generated type: the DDS type name (`std_msgs::msg::dds_::String_`) and the REP-2011
/// type hash (`RIHS01_<sha256>`). Both are part of every rmw_zenoh key, so a wrong value means ROS nodes never
/// match. Specializations are generated by scripts/gen_zn_type_info.bash from a ROS 2 Jazzy install — see
/// TypeInfoTable.hpp. A type without one fails to compile when used with Publisher/Subscriber.
template <typename T>
struct TypeInfo;

} // namespace rbq_sdk::zn

#define RBQ_ZN_TYPE_INFO(CXX_TYPE, DDS_NAME, HASH)                    \
    template <>                                                       \
    struct rbq_sdk::zn::TypeInfo<CXX_TYPE> {                          \
        static constexpr const char* dds_name = DDS_NAME;             \
        static constexpr const char* hash = HASH;                     \
    };
